class Solution {
    public int convertArray(int[] nums) {
        int n = nums.length;
        int[] rev = new int[n];
        for (int i = 0; i < n; i++) rev[i] = nums[n - 1 - i];
        return Math.min(cost(nums), cost(rev));
    }

    // slope trick: min ops to make non-decreasing
    private int cost(int[] a) {
        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
        int ops = 0;
        for (int x : a) {
            pq.add(x);
            if (pq.peek() > x) {
                ops += pq.poll() - x;
                pq.add(x);
            }
        }
        return ops;
    }
}
